//! Optional, explicitly selected preview music. Never generate or auto-play a test oscillator.
//! Generated by Codex (GPT-6.1 sol).
use std::path::Path;

pub struct Phrase {
    samples: Vec<i16>,
    cursor: usize,
}
impl Phrase {
    pub fn read(path: &Path) -> Result<Self, String> {
        // A bounded local test fixture, not a general-purpose media decoder.
        let len = std::fs::metadata(path).map_err(|e| e.to_string())?.len();
        if len > 6_000_000 {
            return Err("Preview WAV must be at most 30 seconds / 6 MB.".into());
        }
        Self::decode(&std::fs::read(path).map_err(|e| e.to_string())?)
    }
    fn decode(bytes: &[u8]) -> Result<Self, String> {
        let fail = || {
            "Preview requires a valid 44.1 kHz stereo 16-bit PCM WAV (at most 30 seconds)."
                .to_string()
        };
        if bytes.len() < 12 || &bytes[..4] != b"RIFF" || &bytes[8..12] != b"WAVE" {
            return Err(fail());
        }
        let end = u32::from_le_bytes(bytes[4..8].try_into().unwrap()) as usize + 8;
        if end > bytes.len() || end < 12 {
            return Err(fail());
        }
        let mut at = 12;
        let mut format = false;
        let mut pcm = None;
        while at < end {
            if end - at < 8 {
                return Err(fail());
            }
            let tag = &bytes[at..at + 4];
            let n = u32::from_le_bytes(bytes[at + 4..at + 8].try_into().unwrap()) as usize;
            at += 8;
            if n > end - at {
                return Err(fail());
            }
            let chunk = &bytes[at..at + n];
            if tag == b"fmt " {
                if n < 16 {
                    return Err(fail());
                }
                let u16_at = |i| u16::from_le_bytes(chunk[i..i + 2].try_into().unwrap());
                let u32_at = |i| u32::from_le_bytes(chunk[i..i + 4].try_into().unwrap());
                format = u16_at(0) == 1
                    && u16_at(2) == 2
                    && u32_at(4) == 44100
                    && u32_at(8) == 176400
                    && u16_at(12) == 4
                    && u16_at(14) == 16;
            } else if tag == b"data" {
                if pcm.is_some() {
                    return Err(fail());
                }
                pcm = Some(chunk);
            }
            at += n + (n & 1);
            if at > end {
                return Err(fail());
            }
        }
        let pcm = pcm
            .filter(|p| !p.is_empty() && p.len() % 4 == 0 && p.len() <= 44100 * 4 * 30)
            .ok_or_else(fail)?;
        if !format {
            return Err(fail());
        }
        let samples = pcm
            .chunks_exact(2)
            .map(|p| i16::from_le_bytes([p[0], p[1]]))
            .collect();
        Ok(Self { samples, cursor: 0 })
    }
    pub fn next(&mut self, frames: usize) -> Vec<i16> {
        let mut out = Vec::with_capacity(frames * 2);
        for _ in 0..frames * 2 {
            out.push(self.samples[self.cursor]);
            self.cursor = (self.cursor + 1) % self.samples.len();
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    fn fixture() -> Vec<u8> {
        let mut b = b"RIFF\x2c\0\0\0WAVEfmt \x10\0\0\0\x01\0\x02\0".to_vec();
        b.extend(44100u32.to_le_bytes());
        b.extend(176400u32.to_le_bytes());
        b.extend(4u16.to_le_bytes());
        b.extend(16u16.to_le_bytes());
        b.extend(b"data\x08\0\0\0");
        for s in [10i16, -10, 20, -20] {
            b.extend(s.to_le_bytes());
        }
        b
    }
    #[test]
    fn phrase_loops_without_changing_stereo_order() {
        let mut p = Phrase::decode(&fixture()).unwrap();
        assert_eq!(p.next(3), [10, -10, 20, -20, 10, -10]);
        assert_eq!(p.next(1), [20, -20]);
    }
    #[test]
    fn truncated_and_wrong_format_files_are_rejected() {
        let b = fixture();
        for n in 0..b.len() {
            assert!(Phrase::decode(&b[..n]).is_err());
        }
        for (i, v) in [(0, b'X'), (20, 3), (22, 1), (24, 0), (32, 2), (34, 24)] {
            let mut x = b.clone();
            x[i] = v;
            assert!(Phrase::decode(&x).is_err());
        }
        let mut x = b.clone();
        x[40..44].copy_from_slice(&u32::MAX.to_le_bytes());
        assert!(Phrase::decode(&x).is_err());
    }
}
